SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'sorptionsstufen_count', 'Anzahl der Sorptionsstufen (aus dem Register)', 'number', NULL, false, '§5.1.3.1 c)', 'Plan 3: Ausgabe der Gleichung M187-09-D2 (count_rows über sorptionsstufen); „Reihenschaltung von mindestens zwei Sorptionsstufen empfohlen“ (L499) — Gate ≥ 2 ist STAGED (m187-G-8).', 'imported_unverified', 'Um das P-Bindepotenzial des Sorptionsmittels auszunutzen und die Einhaltung der Zielkonzentration dauerhaft sicherstellen zu können, wird eine Reihenschaltung von mindestens zwei Sorptionsstufen empfohlen.', 'derived', NULL, NULL, 'verfahrensvariante_p == ''nachgeschaltete_sorptionsstufe''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'sorptionsstufen_count') AND w.code = 'M187-09' AND s.code = 'DWA-M-187';
