SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'ebct_min_stufe', 'kleinste Filterkontaktzeit EBCT einer Stufe', 'number', 'min', false, '§5.1.3.1 c)', 'Plan 3: Ausgabe der Gleichung M187-09-D3 (min_rows über sorptionsstufen.ebct_min).', 'imported_unverified', 'Aktuell liegen keine ausreichenden Praxiserfahrungen für eine gesicherte Bemessung solcher Anlagen vor. Aus den Betriebsergebnissen einer nachgeschalteten Sorptionsstufe in Form eines offenen, einschichtigen Aufstromfilters im halbtechnischen Maßstab können Filterkontaktzeiten (EBCT) $\geqslant 15 \mathrm{~min}$. und maximale Filtergeschwindigkeiten $<5,0 \mathrm{~m} / \mathrm{h}$ angesetzt werden. Das entspricht einer Mindesthöhe des Filterkörpers von $1,25 \mathrm{~m}$. Im Abstrombetrieb sollten die Filtergeschwindigkeiten auf $<2 \mathrm{~m} / \mathrm{h}$ reduziert werden.', 'derived', NULL, NULL, 'verfahrensvariante_p == ''nachgeschaltete_sorptionsstufe''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'ebct_min_stufe') AND w.code = 'M187-09' AND s.code = 'DWA-M-187';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'h_FK_SS_calc', 'Mindesthöhe des Filterkörpers der Sorptionsstufe aus EBCT und Filtergeschwindigkeit (berechnet)', 'number', 'm', false, '§5.1.3.1 c)', 'Plan 3: Ausgabe der Gleichung M187-09-D1 (EBCT · v_filter_aufstrom / 60; 15 min · 5,0 m/h = 1,25 m — „Das entspricht einer Mindesthöhe des Filterkörpers von 1,25 m“, L497). Das Eingabefeld h_FK_SS (VR ≥ 1.25) bleibt (m187-D-4).', 'imported_unverified', 'Aktuell liegen keine ausreichenden Praxiserfahrungen für eine gesicherte Bemessung solcher Anlagen vor. Aus den Betriebsergebnissen einer nachgeschalteten Sorptionsstufe in Form eines offenen, einschichtigen Aufstromfilters im halbtechnischen Maßstab können Filterkontaktzeiten (EBCT) $\geqslant 15 \mathrm{~min}$. und maximale Filtergeschwindigkeiten $<5,0 \mathrm{~m} / \mathrm{h}$ angesetzt werden. Das entspricht einer Mindesthöhe des Filterkörpers von $1,25 \mathrm{~m}$. Im Abstrombetrieb sollten die Filtergeschwindigkeiten auf $<2 \mathrm{~m} / \mathrm{h}$ reduziert werden.', 'derived', NULL, NULL, 'verfahrensvariante_p == ''nachgeschaltete_sorptionsstufe''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'h_FK_SS_calc') AND w.code = 'M187-09' AND s.code = 'DWA-M-187';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'h_FK_min_spur', 'Filterkörperhöhe nach §5.2.3.1 für die Verfahrensvariante (b: 1 m; c: h_FK ≥ 1 m)', 'number', 'm', false, '§5.2.3.1 b) / c)', 'Plan 3: aus S5_LIMITS_SPUR gefüllt; a) / d) drucken keine Höhe (Feld ausgeblendet). Gate h_FK ≥ h_FK_min_spur anstelle des unbedingten REQ-04-Anteils „h_FK >= 1.0“ (M187-06 / -07) ist STAGED (m187-G-1).', 'imported_unverified', 'Zu b) Bei einer Beimischung von GAK ist eine Filterschichtstärke von 1 m vorzusehen. Die Drosselabflussspende ist auf $q_{\mathrm{Dr}, \mathrm{RBF}} \leqslant 0,03 \mathrm{l} /\left(\mathrm{s} \cdot \mathrm{m}^{2}\right)$ zu begrenzen. — Zu c) Bei der Bestimmung des Filterflächenbedarfs ist sowohl die AFS63-Fracht aus den zu erwartenden Mischwasserentlastungen, als auch aus dem Trockenwetterablauf der Kläranlage zu berücksichtigen. Die Drosselabflussspende ist auf $q_{\text {Dr,RBF }} \leqslant 0,03 \mathrm{l} /\left(\mathrm{s} \cdot \mathrm{m}^{2}\right)$ zu begrenzen. Bei RBF mit Beimischung von GAK zur Mitbehandlung des Kläranlagenablaufs bei Trockenwetter muss der Filter in hydraulisch entkoppelte Segmente aufgeteilt werden. Durch eine alternierende Beschickung kann dann die erforderliche Trockenzeit der nicht beschickten Segmente gewährleistet werden. Die Beschickungsdauer eines Segments sollte 24 h nicht überschreiten. Bei Mischwasserentlastungen können alle Filtersegmente gleichzeitig beschickt werden. Nach einer vollständigen Bespannung aller Segmente ist eine Trockenzeit von 24 h einzuhalten, bevor mit einer erneuten Beschickung mit Kläranlagenablauf begonnen werden kann. Positive Erfahrungen liegen bei einer Aufteilung auf drei Segmente vor. Das Retentionsvolumen eines Segments ist auf den mittleren täglichen Trockenwetterzufluss der Kläranlage ( $Q_{T, d, a M}$ ) zu dimensionieren. Es ist eine Filterkörperhöhe von $h_{\mathrm{FK}} \geqslant 1 \mathrm{~m}$ vorzusehen. Des Weiteren sind separate Zulauf-/Verteilrinnen erforderlich, da insbesondere bei geringen Trockenwetterzuflüssen (auch in den Nachtstunden) eine gesicherte (optimale) flächenhafte Beschickung gewährleistet sein muss.', 'lookup_fill', '{"source_label":"§5.2.3.1"}'::jsonb, '{"table_code":"S5_LIMITS_SPUR","role":"limit","keys":[{"column":"variante_spur","from_symbol":"verfahrensvariante_spurenstoffe"}],"value":"h_fk_min_m"}'::jsonb, 'verfahrensvariante_spurenstoffe IN {gak, mitbehandlung_ka}', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'h_FK_min_spur') AND w.code = 'M187-11' AND s.code = 'DWA-M-187';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'q_Dr_RBF_limit_spur', 'Drosselabflussspende nach §5.2.3.1 für die Verfahrensvariante (a: auf 0,01; b / c: ≤ 0,03 l/(s·m²))', 'number', 'l/(s·m²)', false, '§5.2.3.1', 'Plan 3: aus S5_LIMITS_SPUR gefüllt (a) „Begrenzung … auf 0,01“ ohne gedruckten Operator, m187-J-2; b) / c) „≤ 0,03“). Gates q_Dr_RBF ≤ q_Dr_RBF_limit_spur anstelle der sich widersprechenden REQ-03 (≤ 0,03) / REQ-04 (== 0,01) sind STAGED (m187-G-1).', 'imported_unverified', 'Zu a) Die Erhöhung der Kontaktzeit erfordert eine Begrenzung der Drosselabflussspende $q_{\text {Dr, RBF }}$ auf $0,01 \mathrm{l} /\left(\mathrm{s} \cdot \mathrm{m}^{2}\right)$ (siehe Christoffels et al. 2014). — Zu b) Bei einer Beimischung von GAK ist eine Filterschichtstärke von 1 m vorzusehen. Die Drosselabflussspende ist auf $q_{\mathrm{Dr}, \mathrm{RBF}} \leqslant 0,03 \mathrm{l} /\left(\mathrm{s} \cdot \mathrm{m}^{2}\right)$ zu begrenzen. — Zu c) Bei der Bestimmung des Filterflächenbedarfs ist sowohl die AFS63-Fracht aus den zu erwartenden Mischwasserentlastungen, als auch aus dem Trockenwetterablauf der Kläranlage zu berücksichtigen. Die Drosselabflussspende ist auf $q_{\text {Dr,RBF }} \leqslant 0,03 \mathrm{l} /\left(\mathrm{s} \cdot \mathrm{m}^{2}\right)$ zu begrenzen. Bei RBF mit Beimischung von GAK zur Mitbehandlung des Kläranlagenablaufs bei Trockenwetter muss der Filter in hydraulisch entkoppelte Segmente aufgeteilt werden. Durch eine alternierende Beschickung kann dann die erforderliche Trockenzeit der nicht beschickten Segmente gewährleistet werden. Die Beschickungsdauer eines Segments sollte 24 h nicht überschreiten. Bei Mischwasserentlastungen können alle Filtersegmente gleichzeitig beschickt werden. Nach einer vollständigen Bespannung aller Segmente ist eine Trockenzeit von 24 h einzuhalten, bevor mit einer erneuten Beschickung mit Kläranlagenablauf begonnen werden kann. Positive Erfahrungen liegen bei einer Aufteilung auf drei Segmente vor. Das Retentionsvolumen eines Segments ist auf den mittleren täglichen Trockenwetterzufluss der Kläranlage ( $Q_{T, d, a M}$ ) zu dimensionieren. Es ist eine Filterkörperhöhe von $h_{\mathrm{FK}} \geqslant 1 \mathrm{~m}$ vorzusehen. Des Weiteren sind separate Zulauf-/Verteilrinnen erforderlich, da insbesondere bei geringen Trockenwetterzuflüssen (auch in den Nachtstunden) eine gesicherte (optimale) flächenhafte Beschickung gewährleistet sein muss.', 'lookup_fill', '{"source_label":"§5.2.3.1"}'::jsonb, '{"table_code":"S5_LIMITS_SPUR","role":"limit","keys":[{"column":"variante_spur","from_symbol":"verfahrensvariante_spurenstoffe"}],"value":"q_dr_rbf"}'::jsonb, 'verfahrensvariante_spurenstoffe != ''nachgeschaltete_stufe''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'q_Dr_RBF_limit_spur') AND w.code = 'M187-11' AND s.code = 'DWA-M-187';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'q_Dr_RBF_vorgabe_spur', 'Drosselabflussspende — gedruckte Vorgabe (§5.2.3.1, Wortlaut)', 'text', NULL, false, '§5.2.3.1', 'Plan 3: der gedruckte Satzteil zur Drosselabflussspende der gewählten Verfahrensvariante (zeigt den Operator „auf“ bzw. „≤“ so, wie er gedruckt ist).', 'imported_unverified', 'Zu a) Die Erhöhung der Kontaktzeit erfordert eine Begrenzung der Drosselabflussspende $q_{\text {Dr, RBF }}$ auf $0,01 \mathrm{l} /\left(\mathrm{s} \cdot \mathrm{m}^{2}\right)$ (siehe Christoffels et al. 2014). — Zu b) Bei einer Beimischung von GAK ist eine Filterschichtstärke von 1 m vorzusehen. Die Drosselabflussspende ist auf $q_{\mathrm{Dr}, \mathrm{RBF}} \leqslant 0,03 \mathrm{l} /\left(\mathrm{s} \cdot \mathrm{m}^{2}\right)$ zu begrenzen. — Zu c) Bei der Bestimmung des Filterflächenbedarfs ist sowohl die AFS63-Fracht aus den zu erwartenden Mischwasserentlastungen, als auch aus dem Trockenwetterablauf der Kläranlage zu berücksichtigen. Die Drosselabflussspende ist auf $q_{\text {Dr,RBF }} \leqslant 0,03 \mathrm{l} /\left(\mathrm{s} \cdot \mathrm{m}^{2}\right)$ zu begrenzen. Bei RBF mit Beimischung von GAK zur Mitbehandlung des Kläranlagenablaufs bei Trockenwetter muss der Filter in hydraulisch entkoppelte Segmente aufgeteilt werden. Durch eine alternierende Beschickung kann dann die erforderliche Trockenzeit der nicht beschickten Segmente gewährleistet werden. Die Beschickungsdauer eines Segments sollte 24 h nicht überschreiten. Bei Mischwasserentlastungen können alle Filtersegmente gleichzeitig beschickt werden. Nach einer vollständigen Bespannung aller Segmente ist eine Trockenzeit von 24 h einzuhalten, bevor mit einer erneuten Beschickung mit Kläranlagenablauf begonnen werden kann. Positive Erfahrungen liegen bei einer Aufteilung auf drei Segmente vor. Das Retentionsvolumen eines Segments ist auf den mittleren täglichen Trockenwetterzufluss der Kläranlage ( $Q_{T, d, a M}$ ) zu dimensionieren. Es ist eine Filterkörperhöhe von $h_{\mathrm{FK}} \geqslant 1 \mathrm{~m}$ vorzusehen. Des Weiteren sind separate Zulauf-/Verteilrinnen erforderlich, da insbesondere bei geringen Trockenwetterzuflüssen (auch in den Nachtstunden) eine gesicherte (optimale) flächenhafte Beschickung gewährleistet sein muss.', 'lookup_fill', '{"source_label":"§5.2.3.1"}'::jsonb, '{"table_code":"S5_LIMITS_SPUR","role":"value","keys":[{"column":"variante_spur","from_symbol":"verfahrensvariante_spurenstoffe"}],"value":"q_dr_text"}'::jsonb, 'verfahrensvariante_spurenstoffe != ''nachgeschaltete_stufe''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'q_Dr_RBF_vorgabe_spur') AND w.code = 'M187-11' AND s.code = 'DWA-M-187';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'filterschichten', 'Filteraufbau nach Bild 3 (je Lage Stärke, GAK-Volumenanteil, CaCO3-Massenanteil)', 'json', NULL, false, '§5.2.3.2, Bild 3', 'Plan 3: Zeilen je Filterschicht (Bild-3-Lage als Zeilenschlüssel); Σ Filtersandlagen → h_FK_lagen (M187-13-D1), Dränagekies → h_Draen_lagen (-D2), Lagen außerhalb des GAK-Bands → schichten_gak_verletzungen (-D3). Die Einzelskalare GAK_volumenanteil_oben / _unten / CaCO3_massenanteil_GAK (an M187-11 übergeben) und h_FK sind Ablösekandidaten (m187-D-1 / D-2).', 'imported_unverified', 'Die empfohlenen Zumischungskonzentrationen sind Bild 3 zu entnehmen. — \hline 10 cm & Filtersand / Meliorationsschicht GAK-Volumenanteil: 10 \% bis 20 \% & \multirow{3}{*}{20 \% CaCO3-Massenanteil dem gesamten Filtersand beimischen} \\
\hline 60 cm & Filtersand & \\
\hline 30 cm & Filtersand GAK-Volumenanteil: 30 \% bis 40 \% & \\
\hline 25 cm & \multicolumn{2}{|l|}{Dränagekies} \\', 'register', '{"title":"Filteraufbau nach Bild 3 (Filterschichten)","subtitle":"Bild 3 — je Lage Soll-Stärke, GAK-Volumenanteil und CaCO3-Massenanteil; die Ist-Stärken summieren sich zu h_FK","add_label":"+ Lage","placement":"section","columns":[{"key":"lage","label":"Lage (Bild 3)","type":"lookup_key","lookup":{"table_code":"BILD3"},"required":true},{"key":"material","label":"Material","type":"lookup_value","lookup":{"table_code":"BILD3","key_column":"lage","value":"material"}},{"key":"dicke_soll_cm","label":"Stärke Bild 3","type":"lookup_value","lookup":{"table_code":"BILD3","key_column":"lage","value":"dicke_cm"}},{"key":"dicke_ist_cm","label":"Stärke geplant","type":"number","unit":"cm","required":true,"min":0,"aria_label":"geplante Schichtstärke in cm"},{"key":"gak_min","label":"GAK min","type":"lookup_value","lookup":{"table_code":"BILD3","key_column":"lage","value":"gak_vol_min_pct"}},{"key":"gak_max","label":"GAK max","type":"lookup_value","lookup":{"table_code":"BILD3","key_column":"lage","value":"gak_vol_max_pct"}},{"key":"gak_vol_pct","label":"GAK-Volumenanteil geplant","type":"number","unit":"%","min":0,"max":100},{"key":"caco3_soll_pct","label":"CaCO3 Bild 3","type":"lookup_value","lookup":{"table_code":"BILD3","key_column":"lage","value":"caco3_massenanteil_pct"}},{"key":"caco3_pct","label":"CaCO3-Massenanteil geplant","type":"number","unit":"%","min":0,"max":100},{"key":"filterwirksam","label":"Filterkörper","type":"lookup_value","lookup":{"table_code":"BILD3","key_column":"lage","value":"filterwirksam"}},{"key":"gak_ok","label":"GAK im Bild-3-Band","type":"derived","expr":"if(gak_min IS NULL, 1, if(gak_vol_pct >= gak_min AND gak_vol_pct <= gak_max, 1, 0))","display":"badge","value_labels":{"0":"nein","1":"ja"}}],"footer":["h_FK_lagen","h_Draen_lagen","schichten_gak_verletzungen"],"note":"Die empfohlenen Zumischungskonzentrationen sind Bild 3 zu entnehmen. Lagen von oben nach unten: 10 cm Filtersand / Meliorationsschicht (GAK 10 % bis 20 %), 60 cm Filtersand, 30 cm Filtersand (GAK 30 % bis 40 %), 25 cm Dränagekies; 20 % CaCO3-Massenanteil dem gesamten Filtersand beimischen. h_FK = Σ der Filtersandlagen (1,00 m = 10 + 60 + 30 cm), h_Drän = Dränagekies. Die Einzelwerte GAK_volumenanteil_oben / _unten / CaCO3_massenanteil_GAK und h_FK bleiben bis m187-D-1 / D-2."}'::jsonb, NULL, 'verfahrensvariante_spurenstoffe IN {gak, mitbehandlung_ka}', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'filterschichten') AND w.code = 'M187-13' AND s.code = 'DWA-M-187';
