INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'filtersegmente', 'Filtersegmente (je Segment Fläche, Retentionsvolumen, Beschickungstag)', 'json', NULL, false, '§5.2.3.1 c), §5.2.4.1', 'Plan 3: Zeilen je hydraulisch entkoppeltem Segment; Anzahl → segmente_count (M187-14-D2), Segmente mit Retentionsvolumen < Q_T,d,aM · 86,4 → segmente_unterdimensioniert (-D3), Σ Fläche → A_F_segmente (-D4). „Positive Erfahrungen liegen bei einer Aufteilung auf drei Segmente vor“ ist Erfahrung, kein Mindestwert (m187-J-3).', 'imported_unverified', 'Zu c) Bei der Bestimmung des Filterflächenbedarfs ist sowohl die AFS63-Fracht aus den zu erwartenden Mischwasserentlastungen, als auch aus dem Trockenwetterablauf der Kläranlage zu berücksichtigen. Die Drosselabflussspende ist auf $q_{\text {Dr,RBF }} \leqslant 0,03 \mathrm{l} /\left(\mathrm{s} \cdot \mathrm{m}^{2}\right)$ zu begrenzen. Bei RBF mit Beimischung von GAK zur Mitbehandlung des Kläranlagenablaufs bei Trockenwetter muss der Filter in hydraulisch entkoppelte Segmente aufgeteilt werden. Durch eine alternierende Beschickung kann dann die erforderliche Trockenzeit der nicht beschickten Segmente gewährleistet werden. Die Beschickungsdauer eines Segments sollte 24 h nicht überschreiten. Bei Mischwasserentlastungen können alle Filtersegmente gleichzeitig beschickt werden. Nach einer vollständigen Bespannung aller Segmente ist eine Trockenzeit von 24 h einzuhalten, bevor mit einer erneuten Beschickung mit Kläranlagenablauf begonnen werden kann. Positive Erfahrungen liegen bei einer Aufteilung auf drei Segmente vor. Das Retentionsvolumen eines Segments ist auf den mittleren täglichen Trockenwetterzufluss der Kläranlage ( $Q_{T, d, a M}$ ) zu dimensionieren. Es ist eine Filterkörperhöhe von $h_{\mathrm{FK}} \geqslant 1 \mathrm{~m}$ vorzusehen. Des Weiteren sind separate Zulauf-/Verteilrinnen erforderlich, da insbesondere bei geringen Trockenwetterzuflüssen (auch in den Nachtstunden) eine gesicherte (optimale) flächenhafte Beschickung gewährleistet sein muss. — Bei kontinuierlicher Beschickung mit dem Ablauf einer Kläranlage (Variante c) als 4. Reinigungsstufe während der Trockenwetterphase muss sichergestellt werden, dass die Filtersegmente regelmäßig leerlaufen und trockenfallen. Deshalb ist ein RBF zur gezielten Spurenstoffelimination während der Trockenwetterphase in mehrere Segmente aufzuteilen. Positive Erfahrungen liegen bei einer Aufteilung auf drei Segmente vor, wobei zum Beispiel Segment 1 an Tag 1 beschickt wird ( 24 h ), an Tag 2 leerläuft (Segment 2 wird beschickt) und an Tag 3 abtrocknen kann (Segment 3 wird beschickt). Bei der Inanspruchnahme aller Segmente im Mischwasserfall ist zu beachten, dass nach dem Entlastungsereignis alle Segmente des RBF zur Wiederbelüftung des Filtermaterials leerlaufen und 24 h abtrocknen müssen. Danach kann mit der erneuten Beschickung mit Abwasser aus dem Kläranlagenablauf begonnen werden.', 'register', '{"title":"Filtersegmente (hydraulisch entkoppelt)","subtitle":"§5.2.3.1 c) — je Segment Fläche, Retentionsvolumen und Beschickungstag; Retentionsvolumen ≥ Q_T,d,aM · 1 d","add_label":"+ Segment","placement":"section","columns":[{"key":"label","label":"Segment","type":"text","required":true},{"key":"flaeche_m2","label":"Fläche","type":"number","unit":"m²","required":true,"min":0},{"key":"retentionsvolumen_m3","label":"Retentionsvolumen","type":"number","unit":"m³","required":true,"min":0},{"key":"beschickungstag","label":"Beschickungstag (Rotation)","type":"text","datalist":["Tag 1","Tag 2","Tag 3"]},{"key":"v_soll_m3","label":"Soll = Q_T,d,aM · 86,4","type":"derived","expr":"Q_T_d_aM * 86.4"},{"key":"v_ok","label":"Volumen ausreichend","type":"derived","expr":"if(retentionsvolumen_m3 >= v_soll_m3, 1, 0)","display":"badge","value_labels":{"0":"nein","1":"ja"}}],"footer":["segmente_count","V_segment_soll","segmente_unterdimensioniert","A_F_segmente"],"note":"Zu c) Bei der Bestimmung des Filterflächenbedarfs ist sowohl die AFS63-Fracht aus den zu erwartenden Mischwasserentlastungen, als auch aus dem Trockenwetterablauf der Kläranlage zu berücksichtigen. Die Drosselabflussspende ist auf $q_{\\text {Dr,RBF }} \\leqslant 0,03 \\mathrm{l} /\\left(\\mathrm{s} \\cdot \\mathrm{m}^{2}\\right)$ zu begrenzen. Bei RBF mit Beimischung von GAK zur Mitbehandlung des Kläranlagenablaufs bei Trockenwetter muss der Filter in hydraulisch entkoppelte Segmente aufgeteilt werden. Durch eine alternierende Beschickung kann dann die erforderliche Trockenzeit der nicht beschickten Segmente gewährleistet werden. Die Beschickungsdauer eines Segments sollte 24 h nicht überschreiten. Bei Mischwasserentlastungen können alle Filtersegmente gleichzeitig beschickt werden. Nach einer vollständigen Bespannung aller Segmente ist eine Trockenzeit von 24 h einzuhalten, bevor mit einer erneuten Beschickung mit Kläranlagenablauf begonnen werden kann. Positive Erfahrungen liegen bei einer Aufteilung auf drei Segmente vor. Das Retentionsvolumen eines Segments ist auf den mittleren täglichen Trockenwetterzufluss der Kläranlage ( $Q_{T, d, a M}$ ) zu dimensionieren. Es ist eine Filterkörperhöhe von $h_{\\mathrm{FK}} \\geqslant 1 \\mathrm{~m}$ vorzusehen. Des Weiteren sind separate Zulauf-/Verteilrinnen erforderlich, da insbesondere bei geringen Trockenwetterzuflüssen (auch in den Nachtstunden) eine gesicherte (optimale) flächenhafte Beschickung gewährleistet sein muss. Bei kontinuierlicher Beschickung mit dem Ablauf einer Kläranlage (Variante c) als 4. Reinigungsstufe während der Trockenwetterphase muss sichergestellt werden, dass die Filtersegmente regelmäßig leerlaufen und trockenfallen. Deshalb ist ein RBF zur gezielten Spurenstoffelimination während der Trockenwetterphase in mehrere Segmente aufzuteilen. Positive Erfahrungen liegen bei einer Aufteilung auf drei Segmente vor, wobei zum Beispiel Segment 1 an Tag 1 beschickt wird ( 24 h ), an Tag 2 leerläuft (Segment 2 wird beschickt) und an Tag 3 abtrocknen kann (Segment 3 wird beschickt). Bei der Inanspruchnahme aller Segmente im Mischwasserfall ist zu beachten, dass nach dem Entlastungsereignis alle Segmente des RBF zur Wiederbelüftung des Filtermaterials leerlaufen und 24 h abtrocknen müssen. Danach kann mit der erneuten Beschickung mit Abwasser aus dem Kläranlagenablauf begonnen werden. Q_T,d,aM in l/s · 86,4 = m³/d (Umrechnung, keine gedruckte Gleichung — m187-F-1)."}'::jsonb, NULL, 'verfahrensvariante_spurenstoffe == ''mitbehandlung_ka''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'filtersegmente') AND w.code = 'M187-14' AND s.code = 'DWA-M-187';
