FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'segmente_unterdimensioniert') AND w.code = 'M187-14' AND s.code = 'DWA-M-187';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'A_F_segmente', 'Filterfläche aller Segmente (Σ)', 'number', 'm²', false, '§5.2.3.1 c)', 'Plan 3: Ausgabe der Gleichung M187-14-D4 (sum_rows über filtersegmente.flaeche_m2); der Filterflächenbedarf nach AFS63-Fracht (Mischwasser + Trockenwetterablauf) bleibt die DWA-A 178-Bemessung.', 'imported_unverified', 'Zu c) Bei der Bestimmung des Filterflächenbedarfs ist sowohl die AFS63-Fracht aus den zu erwartenden Mischwasserentlastungen, als auch aus dem Trockenwetterablauf der Kläranlage zu berücksichtigen. Die Drosselabflussspende ist auf $q_{\text {Dr,RBF }} \leqslant 0,03 \mathrm{l} /\left(\mathrm{s} \cdot \mathrm{m}^{2}\right)$ zu begrenzen. Bei RBF mit Beimischung von GAK zur Mitbehandlung des Kläranlagenablaufs bei Trockenwetter muss der Filter in hydraulisch entkoppelte Segmente aufgeteilt werden. Durch eine alternierende Beschickung kann dann die erforderliche Trockenzeit der nicht beschickten Segmente gewährleistet werden. Die Beschickungsdauer eines Segments sollte 24 h nicht überschreiten. Bei Mischwasserentlastungen können alle Filtersegmente gleichzeitig beschickt werden. Nach einer vollständigen Bespannung aller Segmente ist eine Trockenzeit von 24 h einzuhalten, bevor mit einer erneuten Beschickung mit Kläranlagenablauf begonnen werden kann. Positive Erfahrungen liegen bei einer Aufteilung auf drei Segmente vor. Das Retentionsvolumen eines Segments ist auf den mittleren täglichen Trockenwetterzufluss der Kläranlage ( $Q_{T, d, a M}$ ) zu dimensionieren. Es ist eine Filterkörperhöhe von $h_{\mathrm{FK}} \geqslant 1 \mathrm{~m}$ vorzusehen. Des Weiteren sind separate Zulauf-/Verteilrinnen erforderlich, da insbesondere bei geringen Trockenwetterzuflüssen (auch in den Nachtstunden) eine gesicherte (optimale) flächenhafte Beschickung gewährleistet sein muss.', 'derived', NULL, NULL, 'verfahrensvariante_spurenstoffe == ''mitbehandlung_ka''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'A_F_segmente') AND w.code = 'M187-14' AND s.code = 'DWA-M-187';
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'sonderanwendung == ''mikroorganismen''' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'KBE' AND w.code = 'M187-16' AND s.code = 'DWA-M-187' AND f.active AND f.visible_when IS NULL;
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'sonderanwendung == ''mikroorganismen''' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'MPN' AND w.code = 'M187-16' AND s.code = 'DWA-M-187' AND f.active AND f.visible_when IS NULL;
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'sonderanwendung == ''mikroorganismen''' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'PBE' AND w.code = 'M187-16' AND s.code = 'DWA-M-187' AND f.active AND f.visible_when IS NULL;
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'sonderanwendung == ''mikroorganismen''' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'logstufen_rueckhalt' AND w.code = 'M187-16' AND s.code = 'DWA-M-187' AND f.active AND f.visible_when IS NULL;
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'q_Dr_RBF_limit_mikro', 'Drosselabflussspende bei Volleinstau nach §5.3.3.1 (q_Dr,RBF = 0,01 l/(s·m²))', 'number', 'l/(s·m²)', false, '§5.3.3.1', 'Plan 3: aus S5_LIMITS_APP für sonderanwendung = mikroorganismen gefüllt (locked, „ist … sicherzustellen“); Gate q_Dr_RBF == q_Dr_RBF_limit_mikro anstelle des auf M187-06 / -07 unbedingt feuernden REQ-04 ist STAGED (m187-G-1).', 'imported_unverified', 'Die Bemessungsvorgaben und die Empfehlungen zur Nachweisführung gelten gemäß Arbeitsblatt DWA-A 178:2019. Abweichend ist jedoch sicherzustellen, dass bei Volleinstau des Retentionsraums die spezifische Drosselabflussspende auf $q_{\mathrm{Dr}, \mathrm{RBF}}=0,01 \mathrm{l} /\left(\mathrm{s} \cdot \mathrm{m}^{2}\right)$ begrenzt ist. Das Drosselorgan kann ungeregelt ausgeführt werden (WaldhoFF 2008).', 'lookup_fill', '{"source_label":"§5.3.3.1"}'::jsonb, '{"table_code":"S5_LIMITS_APP","role":"limit","keys":[{"column":"sonderanwendung","from_symbol":"sonderanwendung"}],"value":"q_dr_rbf"}'::jsonb, 'sonderanwendung == ''mikroorganismen''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'q_Dr_RBF_limit_mikro') AND w.code = 'M187-16' AND s.code = 'DWA-M-187';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'h_FK_min_mikro', 'Höhe des Filterkörpers nach §5.3.3.1 für > 1,0 Log-Stufe Rückhalt (h_FK ≥ 1,0 m, sollte)', 'number', 'm', false, '§5.3.3.1', 'Plan 3: aus S5_LIMITS_APP gefüllt; „sollte die Höhe des Filterkörpers h_FK ≥ 1,0 m betragen“ — die Tabelle ist locked, anhaltswert für diese Zeile ist vorgeschlagen (m187-O-2); Gate h_FK ≥ h_FK_min_mikro (warn) ist STAGED (m187-G-1).', 'imported_unverified', 'Der gesamte Filterkörper ist für Mikroorganismen filterwirksam. Um einen Indikatororganismenrückhalt $>1,0$ Log-Stufe (> $90 \%$ ) zu erreichen, sollte die Höhe des Filterkörpers $h_{\text {FK }} \geqslant 1,0 \mathrm{~m}$ betragen (Waldhoff 2008, Ruppelt et al. 2018).', 'lookup_fill', '{"source_label":"§5.3.3.1"}'::jsonb, '{"table_code":"S5_LIMITS_APP","role":"limit","keys":[{"column":"sonderanwendung","from_symbol":"sonderanwendung"}],"value":"h_fk_min_m"}'::jsonb, 'sonderanwendung == ''mikroorganismen''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'h_FK_min_mikro') AND w.code = 'M187-16' AND s.code = 'DWA-M-187';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'indikatororganismen', 'Indikatororganismen (je Organismus Einheit, Zulauf, Ablauf → Log-Stufen)', 'json', NULL, false, '§5.3.2, §5.3.3.1, §5.3.4.3', 'Plan 3: Zeilen je Indikatororganismus (E. coli, intestinale Enterokokken, somatische Coliphagen; KBE / MPN / PBE); Rückhalt = log10(Zulauf / Ablauf); Minimum → log_red_min (M187-16-D1), Anzahl → organismen_count (-D2). Die Einzelskalare KBE / MPN / PBE / logstufen_rueckhalt sind Ablösekandidaten (m187-D-7).', 'imported_unverified', 'Der Rückhalt von pathogenen Mikroorganismen in RBF wurde überwiegend für die Indikatororganismen E. coli und intestinale Enterokokken sowie für somatische Coliphagen untersucht. Die Zulaufbelastungen unterliegen in ihrer stofflichen Belastung starken Schwankungen, was auch für den Gehalt mit Indikatororganismen zutrifft. Diese sind zudem ortspezifisch. — Die Verringerung der Zulauffracht an Indikatororganismen wurde für RBF im Mischsystem umfassend großtechnisch untersucht und beträgt im Mittel $90 \%$ ( 1,0 Log-Stufe), wobei Schwankungen des Ereigniswirkungsgrads im Wesentlichen zwischen $0,5 \mathrm{Log}$-Stufen bis $1,5 \mathrm{Log}$-Stufen auftreten. In Einzelfällen wurden Rückhalte von bis zu 3,0 Log-Stufen nachgewiesen (WaldhoFF 2008). Für somatische Coliphagen ist der Rückhalt geringer mit Werten zwischen 0,5 Log-Stufen bis 1,0 Log-Stufen (Tondera et al. 2019). Die Effekte, welche diese Spannbreiten bedingen, werden in den Folgeabschnitten genannt. — Der gesamte Filterkörper ist für Mikroorganismen filterwirksam. Um einen Indikatororganismenrückhalt $>1,0$ Log-Stufe (> $90 \%$ ) zu erreichen, sollte die Höhe des Filterkörpers $h_{\text {FK }} \geqslant 1,0 \mathrm{~m}$ betragen (Waldhoff 2008, Ruppelt et al. 2018).', 'register', '{"title":"Indikatororganismen (Zulauf / Ablauf → Log-Stufen)","subtitle":"§5.3.2 / §5.3.4.3 — je Organismus Einheit, Zulauf- und Ablaufkonzentration; Rückhalt in Log-Stufen","add_label":"+ Organismus","placement":"section","columns":[{"key":"organismus","label":"Indikatororganismus","type":"enum","options":["e_coli","enterokokken","coliphagen"],"option_labels":{"e_coli":"E. coli","enterokokken":"intestinale Enterokokken","coliphagen":"somatische Coliphagen"},"required":true},{"key":"einheit","label":"Einheit","type":"enum","options":["kbe","mpn","pbe"],"option_labels":{"kbe":"KBE/100 ml","mpn":"MPN/100 ml","pbe":"PBE/100 ml"},"required":true},{"key":"zulauf","label":"Zulauf","type":"number","required":true,"min":0,"aria_label":"Konzentration im Filterzulauf (Anzahl/100 ml)"},{"key":"ablauf","label":"Ablauf","type":"number","required":true,"min":0,"aria_label":"Konzentration im Filterablauf (Anzahl/100 ml)"},{"key":"log_red","label":"Rückhalt (Log-Stufen)","type":"derived","expr":"log10(zulauf / ablauf)"},{"key":"ok","label":"> 1,0 Log-Stufe","type":"derived","expr":"if(log_red > 1.0, 1, 0)","display":"badge","value_labels":{"0":"nein","1":"ja"}}],"footer":["organismen_count","log_red_min"],"note":"Der Rückhalt von pathogenen Mikroorganismen in RBF wurde überwiegend für die Indikatororganismen E. coli und intestinale Enterokokken sowie für somatische Coliphagen untersucht. Die Zulaufbelastungen unterliegen in ihrer stofflichen Belastung starken Schwankungen, was auch für den Gehalt mit Indikatororganismen zutrifft. Diese sind zudem ortspezifisch. Die Verringerung der Zulauffracht an Indikatororganismen wurde für RBF im Mischsystem umfassend großtechnisch untersucht und beträgt im Mittel $90 \\%$ ( 1,0 Log-Stufe), wobei Schwankungen des Ereigniswirkungsgrads im Wesentlichen zwischen $0,5 \\mathrm{Log}$-Stufen bis $1,5 \\mathrm{Log}$-Stufen auftreten. In Einzelfällen wurden Rückhalte von bis zu 3,0 Log-Stufen nachgewiesen (WaldhoFF 2008). Für somatische Coliphagen ist der Rückhalt geringer mit Werten zwischen 0,5 Log-Stufen bis 1,0 Log-Stufen (Tondera et al. 2019). Die Effekte, welche diese Spannbreiten bedingen, werden in den Folgeabschnitten genannt. Ablauf = 0 („nicht nachweisbar“) ist als Log-Stufe nicht definiert — die Nachweisgrenze eintragen; die Wirkungsgradermittlung ist frachtbezogen (§5.3.4.3, L727) und hier je Probe konzentrationsbezogen (m187-F-2). Die Einzelwerte KBE / MPN / PBE / logstufen_rueckhalt bleiben bis m187-D-7."}'::jsonb, NULL, 'sonderanwendung == ''mikroorganismen''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'indikatororganismen') AND w.code = 'M187-16' AND s.code = 'DWA-M-187';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'log_red_min', 'Rückhalt an Indikatororganismen (Minimum über die Organismen, Log-Stufen)', 'number', 'log', false, '§5.3.2, §5.3.3.1', 'Plan 3: Ausgabe der Gleichung M187-16-D1 (min_rows über indikatororganismen.log_red, Zeilen mit ablauf > 0); Ziel > 1,0 Log-Stufe (> 90 %) bei h_FK ≥ 1,0 m (L677). Das Eingabefeld logstufen_rueckhalt (VR > 1.0) bleibt (m187-D-7).', 'imported_unverified', 'Die Verringerung der Zulauffracht an Indikatororganismen wurde für RBF im Mischsystem umfassend großtechnisch untersucht und beträgt im Mittel $90 \%$ ( 1,0 Log-Stufe), wobei Schwankungen des Ereigniswirkungsgrads im Wesentlichen zwischen $0,5 \mathrm{Log}$-Stufen bis $1,5 \mathrm{Log}$-Stufen auftreten. In Einzelfällen wurden Rückhalte von bis zu 3,0 Log-Stufen nachgewiesen (WaldhoFF 2008). Für somatische Coliphagen ist der Rückhalt geringer mit Werten zwischen 0,5 Log-Stufen bis 1,0 Log-Stufen (Tondera et al. 2019). Die Effekte, welche diese Spannbreiten bedingen, werden in den Folgeabschnitten genannt. — Der gesamte Filterkörper ist für Mikroorganismen filterwirksam. Um einen Indikatororganismenrückhalt $>1,0$ Log-Stufe (> $90 \%$ ) zu erreichen, sollte die Höhe des Filterkörpers $h_{\text {FK }} \geqslant 1,0 \mathrm{~m}$ betragen (Waldhoff 2008, Ruppelt et al. 2018).', 'derived', NULL, NULL, 'sonderanwendung == ''mikroorganismen''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'log_red_min') AND w.code = 'M187-16' AND s.code = 'DWA-M-187';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'organismen_count', 'Anzahl der erfassten Indikatororganismen', 'number', NULL, false, '§5.3.2', 'Plan 3: Ausgabe der Gleichung M187-16-D2 (count_rows über indikatororganismen).', 'imported_unverified', 'Der Rückhalt von pathogenen Mikroorganismen in RBF wurde überwiegend für die Indikatororganismen E. coli und intestinale Enterokokken sowie für somatische Coliphagen untersucht. Die Zulaufbelastungen unterliegen in ihrer stofflichen Belastung starken Schwankungen, was auch für den Gehalt mit Indikatororganismen zutrifft. Diese sind zudem ortspezifisch.', 'derived', NULL, NULL, 'sonderanwendung == ''mikroorganismen''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'organismen_count') AND w.code = 'M187-16' AND s.code = 'DWA-M-187';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'UV_dosis_min', 'UV-Mindestdosis nach §5.3.3.5 (200 J/m², sollte nicht unterschritten werden)', 'number', 'J/m²', false, '§5.3.3.5', 'Plan 3: aus S5_3_3_5_UV gefüllt, wenn eine UV-Nachbehandlung eingesetzt wird (anhaltswert: „sollte … nicht unterschritten werden“). Gate IF uv_eingesetzt == ja THEN UV_dosis ≥ UV_dosis_min ist STAGED (m187-G-7); das Ausblenden von UV_dosis ist m187-C-4.', 'imported_unverified', 'Für die Bemessung einer nachgeschalteten UV-Bestrahlung sollte nach derzeitiger Kenntnis in Anlehnung an SCHÖLER (2002) eine Mindestdosis von $200 \mathrm{~J} / \mathrm{m}^{2}$ nicht unterschritten werden.', 'lookup_fill', '{"source_label":"§5.3.3.5"}'::jsonb, '{"table_code":"S5_3_3_5_UV","role":"limit","keys":[{"column":"uv_eingesetzt","from_symbol":"uv_eingesetzt"}],"value":"uv_dosis_min_j_m2"}'::jsonb, 'uv_eingesetzt == ''ja''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'UV_dosis_min') AND w.code = 'M187-18' AND s.code = 'DWA-M-187';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'stoffstromtrennung', 'Abflüsse der Lagerflächen von denen der Verkehrsflächen getrennt (CSB-Konzentration > 3.000 mg/l, §5.4.2.2.2)', 'boolean', NULL, false, '§5.4.2.2.2', 'Plan 3: „Bei häufiger auftretenden CSB-Konzentrationen von > 3.000 mg/l müssen die Abflüsse der Lagerflächen von denen der Verkehrsflächen getrennt werden“ — sichtbar ab CSB_konzentration > 3000; Gate IF CSB_konzentration > 3000 THEN stoffstromtrennung == true (+ sickerwasser_in_rbf == false, unbedingt) ist STAGED (m187-G-3). Das Eingabefeld CSB_grenze_trennung (VR > 3000) ist eine Konstante als Eingabe (m187-D-8).', 'imported_unverified', 'Das Sickerwasser der Lagerflächen und das Niederschlagswasser der Betriebsflächen sind im Regelfall in getrennten Kanalsträngen abzuleiten. Bei häufiger auftretenden CSB-Konzentrationen von $>3.000 \mathrm{mg} / \mathrm{l}$ müssen die Abflüsse der Lagerflächen von denen der Verkehrsflächen getrennt werden (LAWA-Ad-hoc-AG BIOGASANLAGEN 2018). Das Niederschlagswasser der Betriebsflächen darf in die RBFA eingeleitet werden. Das Sickerwasser ist für eine Behandlung mit einem RBF zu hoch belastet und darf daher nicht in die RBFA eingeleitet werden. Es ist auch sicherzustellen, dass keine größeren Mengen an organischem Material (zum Beispiel durch Zwischenlagerung oder Verladung) und auch kein oberflächlich abfließendes Sickerwasser auf die Betriebsflächen gelangt. Sofern dieses der Fall ist, sind bauliche Veränderungen an der Flächenentwässerung durchzuführen oder es muss ein anderes Behandlungsverfahren gewählt werden.', 'attestation', NULL, NULL, 'CSB_konzentration > 3000', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'stoffstromtrennung') AND w.code = 'M187-19' AND s.code = 'DWA-M-187';
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'daten_vorhanden == ''ja''' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'B_CSB' AND w.code = 'M187-20' AND s.code = 'DWA-M-187' AND f.active AND f.visible_when IS NULL;
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'daten_vorhanden == ''nein''' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'A_F_pro_AEb' AND w.code = 'M187-20' AND s.code = 'DWA-M-187' AND f.active AND f.visible_when IS NULL;
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'daten_vorhanden', 'Liegen CSB-Frachtdaten für die Bemessung vor? (§5.4.3)', 'enum', NULL, false, '§5.4.3', 'Plan 3: Weiche des §5.4.3 — mit Daten: CSB-Fracht ≤ 20 g CSB/(m²·d) bezogen auf die Gesamtfilterfläche; „Liegen keine Daten vor, muss die Gesamtfilterfläche mindestens 750 m²/ha A_E,b betragen.“ REQ-05 verlangt heute beides zugleich — Ersatz durch IF daten_vorhanden THEN … ist STAGED (m187-G-2).', 'imported_unverified', 'Die Filterfläche ist so zu bemessen, dass die CSB-Fracht $\leqslant 20 \mathrm{~g}$ CSB $/\left(\mathrm{m}^{2} \cdot \mathrm{~d}\right)$ bezogen auf die Gesamtfilterfläche im Jahresdurchschnitt beträgt. Liegen keine Daten vor, muss die Gesamtfilterfläche mindestens $750 \mathrm{~m}^{2} / \mathrm{ha} A_{\mathrm{E}, \mathrm{b}}$ betragen.', 'select_one', NULL, NULL, NULL, '[{"value":"ja","label_de":"ja — CSB-Frachtdaten liegen vor (Bemessung über B_CSB ≤ 20 g/(m²·d))","order_index":0},{"value":"nein","label_de":"nein — keine Daten (Gesamtfilterfläche ≥ 750 m²/ha A_E,b)","order_index":1}]'::jsonb, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'daten_vorhanden') AND w.code = 'M187-20' AND s.code = 'DWA-M-187';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'CSB_fracht_d', 'CSB-Fracht auf den RBF im Jahresdurchschnitt', 'number', 'g CSB/d', false, '§5.4.3', 'Plan 3: mittlere tägliche CSB-Fracht (Jahresdurchschnitt) auf die Gesamtfilterfläche — Eingabe für B_CSB_calc (M187-20-D5).', 'imported_unverified', 'Die Filterfläche ist so zu bemessen, dass die CSB-Fracht $\leqslant 20 \mathrm{~g}$ CSB $/\left(\mathrm{m}^{2} \cdot \mathrm{~d}\right)$ bezogen auf die Gesamtfilterfläche im Jahresdurchschnitt beträgt. Liegen keine Daten vor, muss die Gesamtfilterfläche mindestens $750 \mathrm{~m}^{2} / \mathrm{ha} A_{\mathrm{E}, \mathrm{b}}$ betragen.', 'scalar', NULL, NULL, 'daten_vorhanden == ''ja''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'CSB_fracht_d') AND w.code = 'M187-20' AND s.code = 'DWA-M-187';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'teilfilterbecken', 'Teilfilterbecken (je Becken Fläche, in Betrieb / Betriebspause)', 'json', NULL, false, '§5.4.3', 'Plan 3: Zeilen je Teilfilterbecken; Anzahl → teilfilter_count (M187-20-D3), Rest zu Vielfachem von vier → teilfilter_rest (-D6), Σ Fläche → A_F_gesamt (-D1), Σ in Betrieb → A_F_aktiv (-D2); je Zeile Förderleistung ≥ 6 l/(m²·min) · Fläche und 20 l/m² · Fläche. Das Eingabefeld anzahl_teilfilter ist Ablösekandidat (m187-D-5); Gate teilfilter_rest == 0 ist STAGED (m187-G-10).', 'imported_unverified', 'Das RBF wird in vier (oder ein Vielfaches von vier) gleich große Teilfilterbecken aufgeteilt. Davon sind jeweils drei gleichzeitig in Betrieb und eins hat Betriebspause. Nach einer Woche Betrieb wird gewechselt, sodass jedes Teilfilterbecken drei Wochen beschickt wird und dann eine Woche Beschickungspause hat. Die in Betrieb befindlichen Teilfilterbecken werden nacheinander jeweils einmal am Tag beschickt. Die Teilfilterbecken müssen nach der Beschickung immer wieder leerlaufen, um eine ausreichende Sauerstoffversorgung im Filter sicherzustellen. Der Beschickungsvolumenstrom der Beschickungseinrichtung muss eine Förderleistung von mindestens $6 \mathrm{l} /\left(\mathrm{m}^{2} \cdot \mathrm{~min}\right)$ bezogen auf die jeweils beschickte Filterfläche betragen. Pro Beschickungsereignis sollten $20 \mathrm{l} / \mathrm{m}^{2}$ bezogen auf die jeweils beschickte Filterfläche gefördert werden. Weitere Bemessungshinweise sind im Arbeitsblatt DWA-A 262:2017 in 4.3.3.2 zu finden.', 'register', '{"title":"Teilfilterbecken","subtitle":"§5.4.3 — vier (oder ein Vielfaches von vier) gleich große Teilfilterbecken; je Becken Fläche und Betriebszustand","add_label":"+ Teilfilterbecken","placement":"section","columns":[{"key":"label","label":"Teilfilterbecken","type":"text","required":true},{"key":"flaeche_m2","label":"Fläche","type":"number","unit":"m²","required":true,"min":0},{"key":"in_betrieb","label":"in Betrieb (nicht in Betriebspause)","type":"boolean"},{"key":"foerder_min_l_min","label":"Förderleistung mind. (6 l/(m²·min))","type":"derived","expr":"flaeche_m2 * lookup(''S5_4_3_ORG'', ''foerderleistung'', ''wert'')"},{"key":"beschickung_soll_l","label":"Beschickung je Ereignis (20 l/m²)","type":"derived","expr":"flaeche_m2 * lookup(''S5_4_3_ORG'', ''beschickung_pro_ereignis'', ''wert'')"}],"footer":["teilfilter_count","teilfilter_rest","A_F_gesamt","A_F_aktiv"],"note":"Das RBF wird in vier (oder ein Vielfaches von vier) gleich große Teilfilterbecken aufgeteilt. Davon sind jeweils drei gleichzeitig in Betrieb und eins hat Betriebspause. Nach einer Woche Betrieb wird gewechselt, sodass jedes Teilfilterbecken drei Wochen beschickt wird und dann eine Woche Beschickungspause hat. Die in Betrieb befindlichen Teilfilterbecken werden nacheinander jeweils einmal am Tag beschickt. Die Teilfilterbecken müssen nach der Beschickung immer wieder leerlaufen, um eine ausreichende Sauerstoffversorgung im Filter sicherzustellen. Der Beschickungsvolumenstrom der Beschickungseinrichtung muss eine Förderleistung von mindestens $6 \\mathrm{l} /\\left(\\mathrm{m}^{2} \\cdot \\mathrm{~min}\\right)$ bezogen auf die jeweils beschickte Filterfläche betragen. Pro Beschickungsereignis sollten $20 \\mathrm{l} / \\mathrm{m}^{2}$ bezogen auf die jeweils beschickte Filterfläche gefördert werden. Weitere Bemessungshinweise sind im Arbeitsblatt DWA-A 262:2017 in 4.3.3.2 zu finden. Förderleistung und Beschickungsmenge sind „bezogen auf die jeweils beschickte Filterfläche“ — je Teilfilterbecken berechnet. Das Eingabefeld anzahl_teilfilter bleibt bis m187-D-5."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'teilfilterbecken') AND w.code = 'M187-20' AND s.code = 'DWA-M-187';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'A_F_gesamt', 'Gesamtfilterfläche (Σ Teilfilterbecken)', 'number', 'm²', false, '§5.4.3', 'Plan 3: Ausgabe der Gleichung M187-20-D1 (sum_rows über teilfilterbecken.flaeche_m2); Bezugsfläche der CSB-Fracht ≤ 20 g/(m²·d) und des Mindestwerts 750 m²/ha A_E,b.', 'imported_unverified', 'Die Filterfläche ist so zu bemessen, dass die CSB-Fracht $\leqslant 20 \mathrm{~g}$ CSB $/\left(\mathrm{m}^{2} \cdot \mathrm{~d}\right)$ bezogen auf die Gesamtfilterfläche im Jahresdurchschnitt beträgt. Liegen keine Daten vor, muss die Gesamtfilterfläche mindestens $750 \mathrm{~m}^{2} / \mathrm{ha} A_{\mathrm{E}, \mathrm{b}}$ betragen.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'A_F_gesamt') AND w.code = 'M187-20' AND s.code = 'DWA-M-187';
