SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'A_F_aktiv', 'Filterfläche der in Betrieb befindlichen Teilfilterbecken (Σ)', 'number', 'm²', false, '§5.4.3', 'Plan 3: Ausgabe der Gleichung M187-20-D2 (sum_rows über teilfilterbecken mit in_betrieb = true); „jeweils drei gleichzeitig in Betrieb und eins hat Betriebspause“.', 'imported_unverified', 'Das RBF wird in vier (oder ein Vielfaches von vier) gleich große Teilfilterbecken aufgeteilt. Davon sind jeweils drei gleichzeitig in Betrieb und eins hat Betriebspause. Nach einer Woche Betrieb wird gewechselt, sodass jedes Teilfilterbecken drei Wochen beschickt wird und dann eine Woche Beschickungspause hat. Die in Betrieb befindlichen Teilfilterbecken werden nacheinander jeweils einmal am Tag beschickt. Die Teilfilterbecken müssen nach der Beschickung immer wieder leerlaufen, um eine ausreichende Sauerstoffversorgung im Filter sicherzustellen. Der Beschickungsvolumenstrom der Beschickungseinrichtung muss eine Förderleistung von mindestens $6 \mathrm{l} /\left(\mathrm{m}^{2} \cdot \mathrm{~min}\right)$ bezogen auf die jeweils beschickte Filterfläche betragen. Pro Beschickungsereignis sollten $20 \mathrm{l} / \mathrm{m}^{2}$ bezogen auf die jeweils beschickte Filterfläche gefördert werden. Weitere Bemessungshinweise sind im Arbeitsblatt DWA-A 262:2017 in 4.3.3.2 zu finden.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'A_F_aktiv') AND w.code = 'M187-20' AND s.code = 'DWA-M-187';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'teilfilter_count', 'Anzahl der Teilfilterbecken (aus dem Register)', 'number', NULL, false, '§5.4.3', 'Plan 3: Ausgabe der Gleichung M187-20-D3 (count_rows über teilfilterbecken). Das Eingabefeld anzahl_teilfilter bleibt (m187-D-5).', 'imported_unverified', 'Das RBF wird in vier (oder ein Vielfaches von vier) gleich große Teilfilterbecken aufgeteilt. Davon sind jeweils drei gleichzeitig in Betrieb und eins hat Betriebspause. Nach einer Woche Betrieb wird gewechselt, sodass jedes Teilfilterbecken drei Wochen beschickt wird und dann eine Woche Beschickungspause hat. Die in Betrieb befindlichen Teilfilterbecken werden nacheinander jeweils einmal am Tag beschickt. Die Teilfilterbecken müssen nach der Beschickung immer wieder leerlaufen, um eine ausreichende Sauerstoffversorgung im Filter sicherzustellen. Der Beschickungsvolumenstrom der Beschickungseinrichtung muss eine Förderleistung von mindestens $6 \mathrm{l} /\left(\mathrm{m}^{2} \cdot \mathrm{~min}\right)$ bezogen auf die jeweils beschickte Filterfläche betragen. Pro Beschickungsereignis sollten $20 \mathrm{l} / \mathrm{m}^{2}$ bezogen auf die jeweils beschickte Filterfläche gefördert werden. Weitere Bemessungshinweise sind im Arbeitsblatt DWA-A 262:2017 in 4.3.3.2 zu finden.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'teilfilter_count') AND w.code = 'M187-20' AND s.code = 'DWA-M-187';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'teilfilter_rest', 'Rest der Teilfilterbecken-Anzahl zum Vielfachen von vier (0 = vier oder ein Vielfaches von vier)', 'number', NULL, false, '§5.4.3', 'Plan 3: Ausgabe der Gleichung M187-20-D6 (teilfilter_count − 4 · floor(teilfilter_count / 4)); Gate == 0 ist STAGED (m187-G-10).', 'imported_unverified', 'Das RBF wird in vier (oder ein Vielfaches von vier) gleich große Teilfilterbecken aufgeteilt. Davon sind jeweils drei gleichzeitig in Betrieb und eins hat Betriebspause. Nach einer Woche Betrieb wird gewechselt, sodass jedes Teilfilterbecken drei Wochen beschickt wird und dann eine Woche Beschickungspause hat. Die in Betrieb befindlichen Teilfilterbecken werden nacheinander jeweils einmal am Tag beschickt. Die Teilfilterbecken müssen nach der Beschickung immer wieder leerlaufen, um eine ausreichende Sauerstoffversorgung im Filter sicherzustellen. Der Beschickungsvolumenstrom der Beschickungseinrichtung muss eine Förderleistung von mindestens $6 \mathrm{l} /\left(\mathrm{m}^{2} \cdot \mathrm{~min}\right)$ bezogen auf die jeweils beschickte Filterfläche betragen. Pro Beschickungsereignis sollten $20 \mathrm{l} / \mathrm{m}^{2}$ bezogen auf die jeweils beschickte Filterfläche gefördert werden. Weitere Bemessungshinweise sind im Arbeitsblatt DWA-A 262:2017 in 4.3.3.2 zu finden.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'teilfilter_rest') AND w.code = 'M187-20' AND s.code = 'DWA-M-187';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'A_F_min_ohne_daten', 'Mindest-Gesamtfilterfläche ohne Daten (750 m²/ha · A_E,b)', 'number', 'm²', false, '§5.4.3', 'Plan 3: Ausgabe der Gleichung M187-20-D4 (lookup S5_4_3_ORG a_f_pro_aeb · A_E_b); nur ohne CSB-Frachtdaten. Gate A_F_gesamt ≥ A_F_min_ohne_daten ist STAGED (m187-G-2). Das Eingabefeld A_F_pro_AEb (VR ≥ 750) bleibt (m187-C-5).', 'imported_unverified', 'Die Filterfläche ist so zu bemessen, dass die CSB-Fracht $\leqslant 20 \mathrm{~g}$ CSB $/\left(\mathrm{m}^{2} \cdot \mathrm{~d}\right)$ bezogen auf die Gesamtfilterfläche im Jahresdurchschnitt beträgt. Liegen keine Daten vor, muss die Gesamtfilterfläche mindestens $750 \mathrm{~m}^{2} / \mathrm{ha} A_{\mathrm{E}, \mathrm{b}}$ betragen.', 'derived', NULL, NULL, 'daten_vorhanden == ''nein''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'A_F_min_ohne_daten') AND w.code = 'M187-20' AND s.code = 'DWA-M-187';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'B_CSB_calc', 'CSB-Filterflächenbelastung (berechnet: CSB-Fracht / Gesamtfilterfläche)', 'number', 'g/(m²·d)', false, '§5.4.3', 'Plan 3: Ausgabe der Gleichung M187-20-D5 (CSB_fracht_d / A_F_gesamt) — „bezogen auf die Gesamtfilterfläche im Jahresdurchschnitt“; nur mit CSB-Frachtdaten. Gate B_CSB_calc ≤ 20 ist STAGED (m187-G-2). Das Eingabefeld B_CSB (VR ≤ 20) bleibt (m187-C-5).', 'imported_unverified', 'Die Filterfläche ist so zu bemessen, dass die CSB-Fracht $\leqslant 20 \mathrm{~g}$ CSB $/\left(\mathrm{m}^{2} \cdot \mathrm{~d}\right)$ bezogen auf die Gesamtfilterfläche im Jahresdurchschnitt beträgt. Liegen keine Daten vor, muss die Gesamtfilterfläche mindestens $750 \mathrm{~m}^{2} / \mathrm{ha} A_{\mathrm{E}, \mathrm{b}}$ betragen.', 'derived', NULL, NULL, 'daten_vorhanden == ''ja''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'B_CSB_calc') AND w.code = 'M187-20' AND s.code = 'DWA-M-187';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'klein_rbf_elemente', 'Klein-RBF Einzelelemente (je Element A_b,a, A_F, h_RR, h_RBF)', 'json', NULL, false, '§5.5.4', 'Plan 3: Zeilen je Einzelelement (auch Verbundsystem); Σ A_F → A_F_sum_klein (M187-22-D1), Σ A_b,a → A_b_a_sum_klein (-D2), Elemente mit A_F < 1,0 m² → elemente_unter_1m2 (-D3), A_F / A_b,a in % → A_F_anteil_calc (-D4), Anzahl → elemente_count (-D6). Die Einzelskalare A_b_a / A_F (Gl. 1) / A_F_anteil_Aba / h_RR / h_RBF sind Ablösekandidaten (m187-D-6); A_F < 1,0 % mit Gl.-2-Nachweis statt REQ-06 „== 1.0“ ist STAGED (m187-G-6).', 'imported_unverified', 'Die spezifische Bodenfilteroberfläche beträgt $A_{\mathrm{F}}=1,0 \%$ der angeschlossenen befestigten Fläche $A_{\mathrm{b}, \mathrm{a}}$. Dies entspricht $A_{\mathrm{F}}=100 \mathrm{~m}^{2} / \mathrm{ha} A_{\mathrm{b}, \mathrm{a}}$ analog dem Arbeitsblatt DWA-A 178:2019 zur Bemessung für Straßenabflüsse. Aus bautechnischen Belangen sollte die absolute Bodenfilteroberfläche von Einzelelementen $A_{\mathrm{F}} \geqslant 1,0 \mathrm{~m}^{2}$ nicht unterschritten werden. — Mit entsprechender Nachweisführung über die zufließende mittlere Jahreswassermenge und der prognostizierten mittleren AFS-Zulaufbelastung (somit das mittlere spezifische Jahresfrachtpotenzial $b_{\mathrm{R}, \mathrm{a}}$ ) sind unter der Einhaltung der maximal zulässigen AFS63-Filterflächenbelastung von $b_{\text {krit }}=7 \mathrm{~kg} /\left(\mathrm{m}^{2} \cdot \mathrm{a}\right)$ gemäß Arbeitsblatt DWA-A 178:2019 auch geringere spezifische Filterflächen von $A_{\mathrm{F}}<1,0 \%$ der angeschlossenen befestigten Fläche $A_{\mathrm{b}, \mathrm{a}}$ möglich.', 'register', '{"title":"Klein-RBF Einzelelemente","subtitle":"§5.5.4 — je Element angeschlossene befestigte Fläche A_b,a und Bodenfilteroberfläche A_F (≥ 1,0 m²); A_F = 1,0 % A_b,a","add_label":"+ Einzelelement","placement":"section","columns":[{"key":"label","label":"Element","type":"text","required":true},{"key":"a_b_a_m2","label":"A_b,a","type":"number","unit":"m²","required":true,"min":0,"aria_label":"angeschlossene befestigte Fläche des Elements in m²"},{"key":"a_f_m2","label":"A_F","type":"number","unit":"m²","required":true,"min":0,"aria_label":"Bodenfilteroberfläche des Elements in m²"},{"key":"anteil_pct","label":"A_F / A_b,a","type":"derived","expr":"a_f_m2 * 100 / a_b_a_m2"},{"key":"a_f_ok","label":"A_F ≥ 1,0 m²","type":"derived","expr":"if(a_f_m2 >= lookup(''S5_5_KLEIN'', ''a_f_element_min_m2'', ''wert''), 1, 0)","display":"badge","value_labels":{"0":"nein","1":"ja"}},{"key":"h_rr","label":"h_RR","type":"number","unit":"m","min":0,"aria_label":"nutzbare Einstauhöhe des Elements"},{"key":"h_rbf","label":"h_RBF","type":"number","unit":"m","min":0,"aria_label":"Einbautiefe des Elements"}],"footer":["elemente_count","A_b_a_sum_klein","A_F_sum_klein","A_F_anteil_calc","elemente_unter_1m2"],"note":"Die spezifische Bodenfilteroberfläche beträgt $A_{\\mathrm{F}}=1,0 \\%$ der angeschlossenen befestigten Fläche $A_{\\mathrm{b}, \\mathrm{a}}$. Dies entspricht $A_{\\mathrm{F}}=100 \\mathrm{~m}^{2} / \\mathrm{ha} A_{\\mathrm{b}, \\mathrm{a}}$ analog dem Arbeitsblatt DWA-A 178:2019 zur Bemessung für Straßenabflüsse. Aus bautechnischen Belangen sollte die absolute Bodenfilteroberfläche von Einzelelementen $A_{\\mathrm{F}} \\geqslant 1,0 \\mathrm{~m}^{2}$ nicht unterschritten werden. Mit entsprechender Nachweisführung über die zufließende mittlere Jahreswassermenge und der prognostizierten mittleren AFS-Zulaufbelastung (somit das mittlere spezifische Jahresfrachtpotenzial $b_{\\mathrm{R}, \\mathrm{a}}$ ) sind unter der Einhaltung der maximal zulässigen AFS63-Filterflächenbelastung von $b_{\\text {krit }}=7 \\mathrm{~kg} /\\left(\\mathrm{m}^{2} \\cdot \\mathrm{a}\\right)$ gemäß Arbeitsblatt DWA-A 178:2019 auch geringere spezifische Filterflächen von $A_{\\mathrm{F}}<1,0 \\%$ der angeschlossenen befestigten Fläche $A_{\\mathrm{b}, \\mathrm{a}}$ möglich. Die Einzelwerte A_b_a / A_F / A_F_anteil_Aba (Gl. 1) und h_RR / h_RBF bleiben bis m187-D-6."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'klein_rbf_elemente') AND w.code = 'M187-22' AND s.code = 'DWA-M-187';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'A_F_sum_klein', 'Bodenfilteroberfläche aller Einzelelemente (Σ A_F)', 'number', 'm²', false, '§5.5.4', 'Plan 3: Ausgabe der Gleichung M187-22-D1 (sum_rows über klein_rbf_elemente.a_f_m2).', 'imported_unverified', 'Die spezifische Bodenfilteroberfläche beträgt $A_{\mathrm{F}}=1,0 \%$ der angeschlossenen befestigten Fläche $A_{\mathrm{b}, \mathrm{a}}$. Dies entspricht $A_{\mathrm{F}}=100 \mathrm{~m}^{2} / \mathrm{ha} A_{\mathrm{b}, \mathrm{a}}$ analog dem Arbeitsblatt DWA-A 178:2019 zur Bemessung für Straßenabflüsse. Aus bautechnischen Belangen sollte die absolute Bodenfilteroberfläche von Einzelelementen $A_{\mathrm{F}} \geqslant 1,0 \mathrm{~m}^{2}$ nicht unterschritten werden.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'A_F_sum_klein') AND w.code = 'M187-22' AND s.code = 'DWA-M-187';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'A_b_a_sum_klein', 'angeschlossene befestigte Fläche aller Einzelelemente (Σ A_b,a)', 'number', 'm²', false, '§5.5.4', 'Plan 3: Ausgabe der Gleichung M187-22-D2 (sum_rows über klein_rbf_elemente.a_b_a_m2); Anwendungsbereich A_b,a < 1 ha (L859) — Gate STAGED (m187-G-6).', 'imported_unverified', 'Die spezifische Bodenfilteroberfläche beträgt $A_{\mathrm{F}}=1,0 \%$ der angeschlossenen befestigten Fläche $A_{\mathrm{b}, \mathrm{a}}$. Dies entspricht $A_{\mathrm{F}}=100 \mathrm{~m}^{2} / \mathrm{ha} A_{\mathrm{b}, \mathrm{a}}$ analog dem Arbeitsblatt DWA-A 178:2019 zur Bemessung für Straßenabflüsse. Aus bautechnischen Belangen sollte die absolute Bodenfilteroberfläche von Einzelelementen $A_{\mathrm{F}} \geqslant 1,0 \mathrm{~m}^{2}$ nicht unterschritten werden.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'A_b_a_sum_klein') AND w.code = 'M187-22' AND s.code = 'DWA-M-187';
