SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'elemente_unter_1m2', 'Einzelelemente mit A_F < 1,0 m² (Anzahl)', 'number', NULL, false, '§5.5.4', 'Plan 3: Ausgabe der Gleichung M187-22-D3 (count_rows über klein_rbf_elemente mit a_f_ok == 0); „sollte … A_F ≥ 1,0 m² nicht unterschritten werden“ (sollte → warn, STAGED m187-G-6).', 'imported_unverified', 'Die spezifische Bodenfilteroberfläche beträgt $A_{\mathrm{F}}=1,0 \%$ der angeschlossenen befestigten Fläche $A_{\mathrm{b}, \mathrm{a}}$. Dies entspricht $A_{\mathrm{F}}=100 \mathrm{~m}^{2} / \mathrm{ha} A_{\mathrm{b}, \mathrm{a}}$ analog dem Arbeitsblatt DWA-A 178:2019 zur Bemessung für Straßenabflüsse. Aus bautechnischen Belangen sollte die absolute Bodenfilteroberfläche von Einzelelementen $A_{\mathrm{F}} \geqslant 1,0 \mathrm{~m}^{2}$ nicht unterschritten werden.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'elemente_unter_1m2') AND w.code = 'M187-22' AND s.code = 'DWA-M-187';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'A_F_anteil_calc', 'spezifische Bodenfilteroberfläche (Σ A_F / Σ A_b,a, berechnet)', 'number', '%', false, '§5.5.4', 'Plan 3: Ausgabe der Gleichung M187-22-D4 (A_F_sum_klein · 100 / A_b_a_sum_klein); Regelwert 1,0 % (= 100 m²/ha); „auch geringere spezifische Filterflächen von A_F < 1,0 % … möglich“ mit b_krit-Nachweis (Gl. 2) — REQ-06 erzwingt heute == 1.0 (m187-G-6). Das Eingabefeld A_F_anteil_Aba bleibt (m187-D-6).', 'imported_unverified', 'Die spezifische Bodenfilteroberfläche beträgt $A_{\mathrm{F}}=1,0 \%$ der angeschlossenen befestigten Fläche $A_{\mathrm{b}, \mathrm{a}}$. Dies entspricht $A_{\mathrm{F}}=100 \mathrm{~m}^{2} / \mathrm{ha} A_{\mathrm{b}, \mathrm{a}}$ analog dem Arbeitsblatt DWA-A 178:2019 zur Bemessung für Straßenabflüsse. Aus bautechnischen Belangen sollte die absolute Bodenfilteroberfläche von Einzelelementen $A_{\mathrm{F}} \geqslant 1,0 \mathrm{~m}^{2}$ nicht unterschritten werden. — Mit entsprechender Nachweisführung über die zufließende mittlere Jahreswassermenge und der prognostizierten mittleren AFS-Zulaufbelastung (somit das mittlere spezifische Jahresfrachtpotenzial $b_{\mathrm{R}, \mathrm{a}}$ ) sind unter der Einhaltung der maximal zulässigen AFS63-Filterflächenbelastung von $b_{\text {krit }}=7 \mathrm{~kg} /\left(\mathrm{m}^{2} \cdot \mathrm{a}\right)$ gemäß Arbeitsblatt DWA-A 178:2019 auch geringere spezifische Filterflächen von $A_{\mathrm{F}}<1,0 \%$ der angeschlossenen befestigten Fläche $A_{\mathrm{b}, \mathrm{a}}$ möglich.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'A_F_anteil_calc') AND w.code = 'M187-22' AND s.code = 'DWA-M-187';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'elemente_count', 'Anzahl der Einzelelemente', 'number', NULL, false, '§5.5.4', 'Plan 3: Ausgabe der Gleichung M187-22-D6 (count_rows über klein_rbf_elemente).', 'imported_unverified', 'Die spezifische Bodenfilteroberfläche beträgt $A_{\mathrm{F}}=1,0 \%$ der angeschlossenen befestigten Fläche $A_{\mathrm{b}, \mathrm{a}}$. Dies entspricht $A_{\mathrm{F}}=100 \mathrm{~m}^{2} / \mathrm{ha} A_{\mathrm{b}, \mathrm{a}}$ analog dem Arbeitsblatt DWA-A 178:2019 zur Bemessung für Straßenabflüsse. Aus bautechnischen Belangen sollte die absolute Bodenfilteroberfläche von Einzelelementen $A_{\mathrm{F}} \geqslant 1,0 \mathrm{~m}^{2}$ nicht unterschritten werden.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'elemente_count') AND w.code = 'M187-22' AND s.code = 'DWA-M-187';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'carbonatschicht_nachweis', 'Carbonatschicht nachgewiesen (h_FK,CaCO3 ≥ 0,10 m aus Carbonatbrechsand mit 80 % CaCO3): 1 = ja, 0 = nein', 'number', NULL, false, '§5.5.3.2.2', 'Plan 3: Ausgabe der Gleichung M187-22-D7 — if(h_FK_CaCO3 >= 0.10 AND CaCO3_massenanteil_carbo == 80, 1, 0); nur bei carbonatschicht_vorhanden = ja sichtbar („In diesem Fall“, L930). Gate IF carbonatschicht_vorhanden == ja THEN h_FK_CaCO3 >= 0.10 AND CaCO3_massenanteil_carbo == 80 ist STAGED (m187-G-12) — bis dahin ist h_FK_min_klein (0,2 m) die Erklärung des Ingenieurs, dieser Nachweis zeigt sie an.', 'imported_unverified', 'Die Anforderungen an das Filtermaterial sind dem Arbeitsblatt DWA-A 178:2019 zu entnehmen, wonach unter anderem ein $\mathrm{CaCO}_{3}$-Massenanteil von $\geqslant 20 \%$ einzuhalten ist. Alternativ zur Melioration des Filtermaterials kann für eine dauerhafte pH -Stabilisierung auch eine Carbonatschicht mit einer Schichtstärke $h_{\mathrm{FK}}, \mathrm{CaCO}_{3} \geqslant 0,10 \mathrm{~m}$ aus einem handelsüblichen Carbonatbrechsand ( 2 mm bis 8 mm ) mit einem $\mathrm{CaCO}_{3}$-Massenanteil von $80 \%$ hergestellt werden. In diesem Fall kann die Filterstärke auf $h_{F K} 0,2 \mathrm{~m}$ verringert werden. Die zuvor geschilderte Deckschicht kann in diesem Fall entfallen. Als weitere Alternative ist auch ein vollständiger Aufbau des Filterkörpers mit Carbonatbrechsand zulässig, aber aus wirtschaftlichen Gründen in der Regel nicht angezeigt.', 'derived', NULL, NULL, 'carbonatschicht_vorhanden == ''ja''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'carbonatschicht_nachweis') AND w.code = 'M187-22' AND s.code = 'DWA-M-187';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'h_FK_min_klein', 'Mindesthöhe des Filterkörpers Klein-RBF (0,25 m; mit Carbonatschicht h_FK,CaCO3 ≥ 0,10 m: 0,2 m)', 'number', 'm', false, '§5.5.3.2.2', 'Plan 3: Ausgabe der Gleichung M187-22-D5 — if(carbonatschicht_vorhanden == ja, 0,2, 0,25) aus S5_LIMITS_APP (klein_rbf: h_fk_carbonat_m / h_fk_min_m); „In diesem Fall kann die Filterstärke auf h_FK 0,2 m verringert werden.“ (L930, ohne gedruckten Operator — m187-J-4). Gate h_FK ≥ h_FK_min_klein anstelle des unbedingten REQ-02 ist STAGED (m187-G-1); die Vorbedingung des 0,2-m-Werts (h_FK,CaCO3 ≥ 0,10 m, 80 % CaCO3) ist die Gleichung M187-22-D7 / das STAGED Gate m187-G-12 — eine Verknüpfung in dieser Gleichung würde den Regelfall ohne Carbonatschicht unentscheidbar machen (Eingaben leer); h_FK_CaCO3 / CaCO3_massenanteil_carbo sind an M187-22 übergeben — ihr Ausblenden ist m187-C-3.', 'imported_unverified', 'Der Filterkörper muss einschichtig mit ebener Oberfläche hergestellt werden. Die erforderliche Höhe des Filterkörpers beträgt im konsolidierten Zustand $h_{\mathrm{FK}} \geqslant 0,25 \mathrm{~m}$. Hinweise zur Filterstabilität und dem nicht zulässigen Einsatz von Geotextilien sind dem Arbeitsblatt DWA-A 178:2019 zu entnehmen. — Die Anforderungen an das Filtermaterial sind dem Arbeitsblatt DWA-A 178:2019 zu entnehmen, wonach unter anderem ein $\mathrm{CaCO}_{3}$-Massenanteil von $\geqslant 20 \%$ einzuhalten ist. Alternativ zur Melioration des Filtermaterials kann für eine dauerhafte pH -Stabilisierung auch eine Carbonatschicht mit einer Schichtstärke $h_{\mathrm{FK}}, \mathrm{CaCO}_{3} \geqslant 0,10 \mathrm{~m}$ aus einem handelsüblichen Carbonatbrechsand ( 2 mm bis 8 mm ) mit einem $\mathrm{CaCO}_{3}$-Massenanteil von $80 \%$ hergestellt werden. In diesem Fall kann die Filterstärke auf $h_{F K} 0,2 \mathrm{~m}$ verringert werden. Die zuvor geschilderte Deckschicht kann in diesem Fall entfallen. Als weitere Alternative ist auch ein vollständiger Aufbau des Filterkörpers mit Carbonatbrechsand zulässig, aber aus wirtschaftlichen Gründen in der Regel nicht angezeigt.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'h_FK_min_klein') AND w.code = 'M187-22' AND s.code = 'DWA-M-187';
UPDATE worksheet_sections ws SET visible_when = 'sonderanwendung == ''mikroorganismen''' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE ws.worksheet_template_id = w.id AND ws.code = 'B' AND w.code = 'M187-16' AND s.code = 'DWA-M-187' AND ws.visible_when IS NULL;
UPDATE worksheet_sections ws SET visible_when = 'sonderanwendung == ''mikroorganismen''' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE ws.worksheet_template_id = w.id AND ws.code = 'D' AND w.code = 'M187-16' AND s.code = 'DWA-M-187' AND ws.visible_when IS NULL;
UPDATE worksheet_sections ws SET visible_when = 'sonderanwendung == ''klein_rbf''' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE ws.worksheet_template_id = w.id AND ws.code = 'B' AND w.code = 'M187-22' AND s.code = 'DWA-M-187' AND ws.visible_when IS NULL;
UPDATE worksheet_sections ws SET visible_when = 'sonderanwendung == ''klein_rbf''' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE ws.worksheet_template_id = w.id AND ws.code = 'D' AND w.code = 'M187-22' AND s.code = 'DWA-M-187' AND ws.visible_when IS NULL;
